"use client";

import { motion, useReducedMotion } from "framer-motion";

const GRID_Y = [8, 26, 44, 62, 80, 98, 116, 134, 152, 170, 188, 206];

const GLOW_SPOTS = [
  { left: "16%", top: "10%", size: 130, duration: 16, drift: 14, className: "bg-amber-200/35" },
  { left: "66%", top: "48%", size: 100, duration: 20, drift: 10, className: "bg-emerald-100/25" },
  { left: "36%", top: "78%", size: 90, duration: 18, drift: 12, className: "bg-amber-100/20" },
];

function GlowSpot({
  left,
  top,
  size,
  duration,
  drift,
  className,
  shouldReduceMotion,
}: {
  left: string;
  top: string;
  size: number;
  duration: number;
  drift: number;
  className: string;
  shouldReduceMotion: boolean;
}) {
  return (
    <motion.div
      aria-hidden
      className={`absolute rounded-full blur-2xl ${className}`}
      style={{ left, top, width: size, height: size }}
      animate={
        shouldReduceMotion
          ? undefined
          : { x: [0, drift, -drift * 0.6, 0], y: [0, -drift * 0.7, drift * 0.4, 0] }
      }
      transition={{ duration, repeat: Infinity, ease: "easeInOut" }}
    />
  );
}

export function WaveCard({ title, description }: { title: string; description: string }) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <div className="relative min-h-[260px] w-full max-w-sm overflow-hidden rounded-2xl border border-emerald-900/15 bg-[#eafff5] dark:border-slate-800 dark:bg-[#022c22]">
      <svg aria-hidden className="absolute inset-0 h-full w-full" viewBox="0 0 300 220" preserveAspectRatio="none">
        <defs>
          <radialGradient id="waveCardBaseLight" cx="30%" cy="20%" r="90%">
            <stop offset="0%" stopColor="#ffffff" stopOpacity="0.9" />
            <stop offset="45%" stopColor="#6ee7b7" stopOpacity="0.55" />
            <stop offset="100%" stopColor="#d1fae5" stopOpacity="1" />
          </radialGradient>
          <radialGradient id="waveCardBaseDark" cx="30%" cy="20%" r="90%">
            <stop offset="0%" stopColor="#6ee7b7" stopOpacity="0.55" />
            <stop offset="45%" stopColor="#047857" stopOpacity="0.92" />
            <stop offset="100%" stopColor="#022c22" stopOpacity="1" />
          </radialGradient>
          <filter id="waveCardCaustics" x="-30%" y="-30%" width="160%" height="160%">
            <feTurbulence type="fractalNoise" baseFrequency="0.012 0.024" numOctaves="2" seed="4" result="noise">
              {!shouldReduceMotion && (
                <animate
                  attributeName="baseFrequency"
                  dur="24s"
                  values="0.012 0.024;0.02 0.03;0.012 0.024"
                  repeatCount="indefinite"
                />
              )}
            </feTurbulence>
            <feDisplacementMap in="SourceGraphic" in2="noise" scale="55" xChannelSelector="R" yChannelSelector="G" result="displaced" />
            <feGaussianBlur in="displaced" stdDeviation="0.6" />
          </filter>
        </defs>
        <rect className="dark:hidden" width="300" height="220" fill="url(#waveCardBaseLight)" />
        <rect className="hidden dark:block" width="300" height="220" fill="url(#waveCardBaseDark)" />
        <g className="dark:hidden" filter="url(#waveCardCaustics)" style={{ mixBlendMode: "multiply" }} stroke="#047857" strokeWidth={1.4} fill="none">
          {GRID_Y.map((y) => (
            <line key={`h-light-${y}`} x1={-30} y1={y} x2={330} y2={y} strokeOpacity={0.22} />
          ))}
          <g transform="rotate(38 150 110)">
            {GRID_Y.map((y) => (
              <line key={`d-light-${y}`} x1={-30} y1={y} x2={330} y2={y} strokeOpacity={0.12} />
            ))}
          </g>
        </g>
        <g className="hidden dark:block" filter="url(#waveCardCaustics)" style={{ mixBlendMode: "screen" }} stroke="#fefce8" strokeWidth={1.4} fill="none">
          {GRID_Y.map((y) => (
            <line key={`h-dark-${y}`} x1={-30} y1={y} x2={330} y2={y} strokeOpacity={0.3} />
          ))}
          <g transform="rotate(38 150 110)">
            {GRID_Y.map((y) => (
              <line key={`d-dark-${y}`} x1={-30} y1={y} x2={330} y2={y} strokeOpacity={0.16} />
            ))}
          </g>
        </g>
      </svg>
      {GLOW_SPOTS.map((spot, i) => (
        <GlowSpot key={i} {...spot} shouldReduceMotion={!!shouldReduceMotion} />
      ))}
      <div className="pointer-events-none absolute inset-x-0 top-0 h-44 bg-[linear-gradient(to_bottom,rgba(234,255,245,0.88)_0%,rgba(234,255,245,0.88)_60%,rgba(234,255,245,0)_100%)] dark:bg-[linear-gradient(to_bottom,rgba(0,0,0,0.82)_0%,rgba(0,0,0,0.82)_60%,rgba(0,0,0,0)_100%)]" />
      <div className="relative z-10 p-6">
        <h3 className="text-base font-semibold text-emerald-950 dark:text-white dark:drop-shadow-[0_1px_2px_rgba(0,0,0,0.5)]">{title}</h3>
        <p className="mt-1.5 text-sm leading-relaxed text-emerald-950/70 dark:text-slate-100 dark:drop-shadow-[0_1px_2px_rgba(0,0,0,0.5)]">{description}</p>
      </div>
    </div>
  );
}
